create table app_users (id uuid primary key, email varchar(254) not null unique, name varchar(80) not null, password_hash varchar(100) not null, created_at timestamp with time zone not null);
create table app_teams (id uuid primary key, name varchar(80) not null, owner_id uuid not null references app_users(id), invite_hash varchar(64) not null unique, created_at timestamp with time zone not null);
create table app_team_members (team_id uuid not null references app_teams(id), user_id uuid not null references app_users(id), role varchar(10) not null check(role in ('OWNER','MEMBER')), primary key(team_id,user_id));
create table app_meetings (id uuid primary key, team_id uuid not null references app_teams(id), title varchar(160) not null, created_by uuid not null references app_users(id), created_at timestamp with time zone not null, status varchar(10) not null check(status in ('OPEN','ENDED')), revision integer not null default 0);
create table transcript_revisions (id uuid primary key, meeting_id uuid not null references app_meetings(id), version integer not null, approved_by uuid not null references app_users(id), created_at timestamp with time zone not null, unique(meeting_id,version));
create table transcript_segments (revision_id uuid not null references transcript_revisions(id), segment_id uuid not null, seq integer not null, received_at timestamp with time zone not null, text varchar(4000) not null, primary key(revision_id,segment_id), unique(revision_id,seq));
create table app_knowledge_boxes (id uuid primary key, team_id uuid not null references app_teams(id), name varchar(80) not null, department varchar(80) not null, unique(team_id,id));
create table app_knowledge_agents (id uuid primary key, team_id uuid not null references app_teams(id), name varchar(80) not null, department varchar(80) not null, unique(team_id,id));
create table app_agent_boxes (team_id uuid not null, agent_id uuid not null, box_id uuid not null, primary key(agent_id,box_id), foreign key(team_id,agent_id) references app_knowledge_agents(team_id,id), foreign key(team_id,box_id) references app_knowledge_boxes(team_id,id));
create table app_knowledge_documents (id uuid primary key, box_id uuid not null references app_knowledge_boxes(id), title varchar(160) not null, content text not null, approved_by uuid not null references app_users(id), created_at timestamp with time zone not null);
create table app_audit (id uuid primary key, team_id uuid not null references app_teams(id), actor_id uuid not null references app_users(id), operation varchar(40) not null, resource_id uuid not null, created_at timestamp with time zone not null);
create index meetings_team_idx on app_meetings(team_id,created_at);
create index documents_box_idx on app_knowledge_documents(box_id);
